import {landmarkSection} from './route-sections.js';
export const ROUTES=[
 {id:'coast',name:'Coastline',tag:'Coastal sprint',description:'Open sea · Palms · Flowing bends',color:'#74d9e6',sections:['Seafront','Harbour','Coastal bends']},
 {id:'city',name:'Neon City',tag:'Urban expressway',description:'Skyline · Flyovers · Underpasses',color:'#e785e6',sections:['Downtown','Skyway','Underpass']},
 {id:'mountain',name:'Mountain Pass',tag:'Alpine challenge',description:'Cliff roads · Tight curves · Elevation',color:'#d5e6a1',sections:['Pine valley','Switchbacks','High pass']}
];
export const validRoute=id=>ROUTES.some(r=>r.id===id)?id:'coast';
export const routeName=id=>ROUTES.find(r=>r.id===id)?.name||'Coastline';
const cycle=d=>((d%3000)+3000)%3000;
export const CITY_FLYOVERS=[{start:360,end:820,height:7.5},{start:2120,end:2530,height:6}];
export const CITY_UNDERPASS={start:1190,end:1390};
const ease=t=>{t=Math.max(0,Math.min(1,t));return t*t*t*(t*(t*6-15)+10);};
function plateau(d,start,end,height){const ramp=Math.min(150,(end-start)*.36);return height*ease((d-start)/ramp)*ease((end-d)/ramp);}
export function cityElevation(distance){const d=cycle(distance);return CITY_FLYOVERS.reduce((h,b)=>h+plateau(d,b.start,b.end,b.height),0)-plateau(d,1090,1480,1.7);}
export function routeSection(id,distance){const special=landmarkSection(id,distance);if(special)return special;const d=cycle(distance);if(id==='city'){if(d>=CITY_UNDERPASS.start&&d<=CITY_UNDERPASS.end)return 'Underpass';if(CITY_FLYOVERS.some(b=>d>b.start&&d<b.end))return 'Skyway';return d>1650?'Skyline district':'Downtown';}if(id==='mountain')return d<650?'Pine valley':d<2200?'Switchbacks':'High pass';return d<950?'Seafront':d<1900?'Harbour':'Coastal bends';}
export function renderRoutes(body,profile,{select}){
 const intro=document.createElement('p');intro.className='routes-note';intro.textContent='Choose a route · Works with every weather world';body.append(intro);const grid=document.createElement('div');grid.className='routes-grid';for(const item of ROUTES){const card=document.createElement('article');card.className='route-card route-'+item.id;card.dataset.item=item.id;const art=document.createElement('div');art.className='route-art has-preview';art.style.backgroundImage='url(assets/routes/preview-'+item.id+'.png)';art.innerHTML=item.id==='city'?'<span class="route-city-towers"></span>':item.id==='mountain'?'<span class="route-mountain-peaks"></span>':'<span class="route-sea"></span>';const path=document.createElementNS('http://www.w3.org/2000/svg','svg');path.setAttribute('viewBox','0 0 300 150');path.innerHTML='<path d="'+(item.id==='mountain'?'M120 160C270 100 40 110 180 70S90 35 170 8':item.id==='city'?'M120 160C120 110 195 108 175 70S165 35 185 8':'M120 160C160 100 210 110 185 60S175 35 210 8')+'" fill="none" stroke="#071522" stroke-width="18"/><path d="'+(item.id==='mountain'?'M120 160C270 100 40 110 180 70S90 35 170 8':item.id==='city'?'M120 160C120 110 195 108 175 70S165 35 185 8':'M120 160C160 100 210 110 185 60S175 35 210 8')+'" fill="none" stroke="'+item.color+'" stroke-width="3" stroke-dasharray="5 5"/>';art.append(path);const label=document.createElement('small');label.textContent=item.tag;const name=document.createElement('h3');name.textContent=item.name;const detail=document.createElement('p');detail.textContent=item.description;const button=document.createElement('button');button.textContent=profile.route===item.id?'Selected':'Drive here ↗';button.disabled=profile.route===item.id;button.classList.toggle('selected',button.disabled);button.setAttribute('aria-label','Select '+item.name);button.onclick=()=>select(item.id);card.append(art,label,name,detail,button);grid.append(card);}body.append(grid);
}
